"""Generated by OpenAI Codex on 2026-11-03. Ranked names and connected pedestrian routing."""

import heapq
import math
from collections import defaultdict
from itertools import pairwise

from services.campus_map import is_building


def normalized(value):
    return " ".join(value.casefold().split())


def edit_distance(first, second):
    previous = list(range(len(second) + 1))
    for i, a in enumerate(first, 1):
        current = [i]
        for j, b in enumerate(second, 1):
            current.append(
                min(current[-1] + 1, previous[j] + 1, previous[j - 1] + (a != b))
            )
        previous = current
    return previous[-1]


def name_rank(query, name):
    q, n = normalized(query), normalized(name)
    category = 0 if n == q else 1 if n.startswith(q) else 2 if q in n else 3
    return category, edit_distance(q, n[:250]), abs(len(n) - len(q)), n


def allowed(tags):
    access = tags.get("foot", tags.get("access", "yes"))
    return (
        access
        not in {"no", "private", "customers", "permit", "agricultural", "forestry"}
        and tags.get("locked") != "yes"
        and not any(key in tags for key in ("foot:conditional", "access:conditional"))
    )


def meters(a, b):
    lat1, lon1, lat2, lon2 = map(math.radians, (*a, *b))
    h = (
        math.sin((lat2 - lat1) / 2) ** 2
        + math.cos(lat1) * math.cos(lat2) * math.sin((lon2 - lon1) / 2) ** 2
    )
    return 6371008.8 * 2 * math.asin(min(1, math.sqrt(h)))


def walking_graph(objects):
    graph = defaultdict(list)
    for obj in objects.values():
        tags = obj["tags"]
        highway = tags.get("highway")
        if (
            obj["type"] != "way"
            or highway not in {"footway", "path", "pedestrian", "steps", "cycleway"}
            or not allowed(tags)
            or tags.get("area") == "yes"
            or tags.get("indoor") == "yes"
            or tags.get("construction") not in {None, "no"}
        ):
            continue
        if highway == "cycleway" and tags.get("foot") not in {
            "yes",
            "designated",
            "permissive",
        }:
            continue
        refs = [ref["id"] for ref in obj["refs"]]
        for a, b in pairwise(refs):
            if a not in objects or b not in objects:
                continue
            nodes = [objects[a], objects[b]]
            if any(
                not allowed(n["tags"])
                or n["tags"].get("barrier")
                in {"wall", "fence", "hedge", "retaining_wall"}
                for n in nodes
            ):
                continue
            distance = meters(nodes[0]["position"], nodes[1]["position"])
            direction = tags.get("oneway:foot", "no")
            graph.setdefault(a, [])
            graph.setdefault(b, [])  # Include vertices that only have incoming edges.
            if direction != "-1":
                graph[a].append((b, distance, obj["id"]))
            if direction not in {"yes", "1", "true"}:
                graph[b].append((a, distance, obj["id"]))
    return graph


def endpoints(key, objects, graph):
    obj = objects[key]
    if not allowed(obj["tags"]):
        return set()
    if is_building(obj):
        return {
            item["id"]
            for item in objects.values()
            if item.get("building_id") == key
            and item["id"] in graph
            and allowed(item["tags"])
            and item["tags"].get("entrance") not in {"no", "exit", "emergency"}
        }
    if obj["type"] == "node":
        return {key} if key in graph else set()
    refs = obj["refs"]
    if obj["type"] == "relation":
        refs = [
            node
            for member in refs
            if member["id"] in objects and member["type"] == "way"
            for node in objects[member["id"]]["refs"]
        ]
    return {ref["id"] for ref in refs if ref["id"] in graph}


def route(objects, start, destination):
    if start not in objects or destination not in objects:
        raise KeyError("Selected location no longer exists")
    graph = walking_graph(objects)
    starts, ends = (
        endpoints(start, objects, graph),
        endpoints(destination, objects, graph),
    )
    if not starts:
        raise ValueError(
            "The starting location has no connected, permitted walking-path entrance. Choose another start or connect its entrance in the map editor."
        )
    if not ends:
        raise ValueError(
            "The destination has no connected, permitted walking-path entrance. Choose another destination or connect its entrance in the map editor."
        )
    queue = [(0.0, node) for node in sorted(starts)]
    heapq.heapify(queue)
    distances = {node: 0.0 for node in starts}
    previous = {}
    finish = None
    while queue:
        distance, node = heapq.heappop(queue)
        if distance != distances[node]:
            continue
        if node in ends:
            finish = node
            break
        for neighbor, length, way in graph[node]:
            candidate = distance + length
            if candidate < distances.get(neighbor, math.inf):
                distances[neighbor] = candidate
                previous[neighbor] = (node, way, length)
                heapq.heappush(queue, (candidate, neighbor))
    if finish is None:
        raise ValueError(
            "No connected walking route exists between these locations in the mapped network."
        )
    nodes = [finish]
    edges = []
    while nodes[-1] in previous:
        node, way, length = previous[nodes[-1]]
        edges.append((way, length))
        nodes.append(node)
    nodes.reverse()
    edges.reverse()
    steps = []
    for way, length in edges:
        tags = objects[way]["tags"]
        if steps and steps[-1]["feature_id"] == way:
            steps[-1]["distance_m"] += length
        else:
            steps.append(
                {
                    "feature_id": way,
                    "name": tags.get("name")
                    or tags.get("highway", "path").replace("_", " "),
                    "distance_m": length,
                    "stairs": tags.get("highway") == "steps",
                }
            )
    for step in steps:
        step["distance_m"] = round(step["distance_m"])
    coordinates = [list(reversed(objects[node]["position"])) for node in nodes]
    if len(coordinates) == 1:
        coordinates.append(coordinates[0])
    return {
        "type": "Feature",
        "geometry": {"type": "LineString", "coordinates": coordinates},
        "properties": {
            "distance_m": round(distances[finish]),
            "duration_minutes": round(distances[finish] / 84, 1),
            "start_node": nodes[0],
            "destination_node": finish,
            "steps": steps,
            "has_stairs": any(step["stairs"] for step in steps),
        },
    }
